("cf_bullet_collision_particle", [
    (store_script_param, ":struck", 1),
    (store_script_param, ":distance", 2),
    # 0 = world (landscape)
    # 1 = hostile agent
    # 2 = dynamic prop
    # 3 = world object (trees, stones, scene interior basic mesh)
    # 4 = mission object (most scene props)
    # 8 = friendly agent
    # 9 = neutral agent
    # 10 = under water
    (this_or_next|eq, ":struck", 0),
    (is_between, ":struck", 2, 5),
    # (eq, ":struck", 10),

    (try_begin),
      # (this_or_next|eq, ":struck", 1),
      # (this_or_next|eq, ":struck", 8),
      # (eq, ":struck", 9),

      # # Blood Particle
      # (assign, ":particle", "psys_bullet_distance_blood"),	# This fired even when the missile was blocked, move to damage trigger
    # (else_try),
      (eq, ":struck", 0),
      (assign, ":particle", "psys_bullet_hit_ground"),
    (else_try),
      (this_or_next|eq, ":struck", 2),
      (eq, ":struck", 3),
      (assign, ":particle", "psys_stone_debris"),
      # (val_div, ":distance", 2),
      (play_sound_at_position, "snd_distant_debris", pos1, sf_vol_10),
    (else_try),
      (eq, ":struck", 4),
      (assign, ":particle", "psys_stone_debris"),
      # (val_div, ":distance", 3),
      (play_sound_at_position, "snd_distant_debris", pos1, sf_vol_10),
    # (else_try),
      # (eq, ":struck", 10),
      # (assign, ":particle", "psys_game_hoof_dust_mud"),
    (else_try),
      (assign, ":particle", "psys_bullet_hit_ground"),
      (play_sound_at_position, "snd_distant_debris", pos1, sf_vol_10),
    (try_end),
	
	(val_div, ":distance", 3),
    (particle_system_burst, ":particle", pos1, ":distance"),
    ]),

