#script_cover_battle_start
("cover_battle_start", #called from all teams at battle start / called from ai teams via battle tactic during battle
  [
    (store_script_param, ":team_no", 1),
    (store_script_param, ":radius", 2),
	
	(scene_prop_get_num_instances, ":total_spr_cover", "spr_cover"),
	#(assign, reg24, ":total_spr_cover"),
	(scene_prop_get_num_instances, ":total_spr_cover_enemy", "spr_cover_enemy"),
	#(assign, reg25, ":total_spr_cover_enemy"),
	#(display_message, "@cover: {reg24},  cover_enemy: {reg25}"),
	
	(try_begin),
        (eq,":team_no","$g_player_team"), #same team as player

        (assign,":cover_prop","spr_cover"),
        (assign,":cover_prop_enemy","spr_cover_enemy"),
		
        (assign,":total",":total_spr_cover"),
        (assign,":total2",":total_spr_cover_enemy"),
      (else_try),
        (assign,":cover_prop","spr_cover_enemy"),
        (assign,":cover_prop_enemy","spr_cover"),
		
		(assign,":total",":total_spr_cover_enemy"),
        (assign,":total2",":total_spr_cover"),
    (try_end),
	
    (try_for_agents, ":agent_id"),
      (agent_slot_eq, ":agent_id", slot_agent_has_ranged,1),
      (agent_slot_eq, ":agent_id", slot_agent_take_cover,-1),
      (neg|agent_slot_ge, ":agent_id", slot_agent_horse_prop,0),
      (agent_is_active, ":agent_id"),
      (agent_is_alive,":agent_id"),
      (agent_is_human,":agent_id"),
      (agent_is_non_player, ":agent_id"),
      (agent_get_team  ,":agent_team", ":agent_id"),
      (eq,":agent_team",":team_no"), #from the same team the script get called from
      (agent_get_horse, ":horse", ":agent_id"),
      (eq, ":horse", -1), #should not be mounted
      (agent_get_wielded_item, ":wielded_item", ":agent_id", 0),
      (gt, ":wielded_item", -1),
      (item_get_type, ":item_type", ":wielded_item"),
      (this_or_next|is_between, ":wielded_item", grenades_begin, grenades_end),
	  (this_or_next|eq, ":item_type", itp_type_bow),
      #(this_or_next|eq, ":item_type", itp_type_crossbow),
      (this_or_next|eq, ":item_type", itp_type_pistol),
      (eq, ":item_type", itp_type_musket),
	  
	  (agent_get_troop_id, ":troop_id", ":agent_id"),
	  (neg|is_between, ":troop_id", infested_mut_begin, infested_end),
	  
	  # ##reduce radius if checked recently. Then skip when check again.
	  # (assign, ":continue", 1),
	  # (agent_get_slot, ":cover_recently", ":agent_id", slot_agent_checked_cover_recently),
	  # (try_begin),
			# (le, ":cover_recently", 0),
			# (store_script_param, ":radius", 2),
			# (agent_set_slot,":agent_id",slot_agent_checked_cover_recently,1),
		# (else_try),
			# (eq, ":cover_recently", 1),
			# (val_div, ":radius", 4),
			# (agent_set_slot,":agent_id",slot_agent_checked_cover_recently,2),
		# (else_try),
			# (eq, ":cover_recently", 2),
			# (assign, ":continue", 0),
			# (agent_set_slot,":agent_id",slot_agent_checked_cover_recently,0),
	  # (try_end),	
	  # (eq, ":continue", 1),
	  
      # (try_begin),
        # (eq,":agent_team","$g_player_team"), #same team as player

        # (assign,":cover_prop","spr_cover"),
        # (assign,":cover_prop_enemy","spr_cover_enemy"),
		
        # (assign,":total","total_spr_cover"),
        # (assign,":total2","total_spr_cover_enemy"),
      # (else_try),
        # (assign,":cover_prop","spr_cover_enemy"),
        # (assign,":cover_prop_enemy","spr_cover"),
		
		# (assign,":total","total_spr_cover_enemy"),
        # (assign,":total2","total_spr_cover"),
      # (try_end),
      (assign,":found",0),
      (assign,":found2",0),
      (assign,":enemy_nearby",0),
      (agent_ai_get_cached_enemy, ":enemy_agent", ":agent_id", 0),
	  
	  (try_begin),	#moved some up here for efficiency
          (ge, ":enemy_agent", 0),
          (agent_is_alive, ":enemy_agent"),
          (neg|agent_slot_ge, ":enemy_agent", slot_agent_is_running_away, 1),
          (agent_get_position, pos0, ":enemy_agent"),
		(else_try),
		  (assign, ":enemy_agent", -2),
      (try_end),

      (agent_get_position,pos65,":agent_id"),

     # (scene_prop_get_num_instances, ":total", ":cover_prop"),

      (try_for_range,":cur_instance",0,":total"),
        (neq,":found",1),
        (scene_prop_get_instance, ":instance_id", ":cover_prop", ":cur_instance"),

        (scene_prop_slot_eq,":instance_id",scene_prop_cover_occupied, 0),

        (prop_instance_get_position, pos66, ":instance_id"),
        (get_distance_between_positions, ":dist", pos66, pos65),
        (le, ":dist", ":radius"), #prop lesser than max radius away

       # (scene_prop_get_num_instances, ":total2", ":cover_prop_enemy"),

        (try_for_range,":cur_instance2",0,":total2"),
          (neq,":found2",1),
          (scene_prop_get_instance, ":instance_id2", ":cover_prop_enemy", ":cur_instance2"),

          (scene_prop_slot_eq,":instance_id2",scene_prop_cover_occupied, 1),

          (prop_instance_get_position, pos67, ":instance_id2"),
          (get_distance_between_positions, ":dist2", pos66, pos67),
          (le, ":dist2", 500), #5m

          (assign,":found2",1),
        (try_end),

        (neq,":found2",1),  #found occupied cover nearby

        #find nearest enemy agent
        # (agent_ai_get_cached_enemy, ":enemy_agent", ":agent_id", 0),
        (try_begin),
          (ge, ":enemy_agent", 0),

          #(agent_is_alive, ":enemy_agent"),

         # (neg|agent_slot_ge, ":enemy_agent", slot_agent_is_running_away, 1),

          #(agent_get_position, pos0, ":enemy_agent"),
          (get_distance_between_positions, ":new_distance", pos0, pos66), #distance enemy agent, choosen prop
		  (val_mul, ":new_distance", 2), #double it as being in cover is still safer - krag
          (lt, ":new_distance", ":dist"),
          (assign,":enemy_nearby",1),
        (try_end),

        (neq,":enemy_nearby",1),  #found enemy which is closer to the cover

        (scene_prop_set_slot,":instance_id",scene_prop_cover_occupied,1),
        (assign,":found",1),
      (try_end),
	  
	  
      (eq,":found",1),

      (try_begin),
        (eq,"$g_covers_active",1),     #this is with auto-cover positions, the block below for scenes with manual positioned covers.
        (agent_get_entry_no, ":entry", "$g_player"), #this block could need improvement
        # (agent_get_entry_no, ":entry", ":agent_id"),
        (entry_point_get_position, pos68, ":entry"),
        (try_begin), #rotate if enemy
          (neq,":agent_team","$g_player_team"),
          (position_rotate_z, pos68, 180),
        (try_end),
        (position_copy_origin,pos68,pos66),
		(try_begin),	# krag add this block to move agents closer to thin cover props
			(scene_prop_slot_ge, ":instance_id", scene_prop_cover_distance_divider, 1),
			(position_move_y,pos68,-50,0), 
		  (else_try),
			(position_move_y,pos68,-150,0), #cheap pos shift #just this line originally in this block - krag
		(try_end),
        (agent_set_scripted_destination,":agent_id",pos68),
      (else_try),
        (agent_set_scripted_destination,":agent_id",pos66),
      (try_end),


      (agent_set_slot,":agent_id",slot_agent_take_cover,0),
      (agent_set_slot,":agent_id",slot_agent_prop_occupied,":instance_id"),
    (try_end),]),


#script_cover_search_player
("cover_search_player", #called from player commands / player team only
  [
    (store_script_param, ":order_pos", 1),
    (store_script_param, ":radius", 2),

    (copy_position, pos65, ":order_pos"),

    (try_for_agents, ":agent_id"),
      (agent_slot_eq, ":agent_id", slot_agent_has_ranged,1),
      (agent_slot_eq, ":agent_id", slot_agent_take_cover,-1),
      (neg|agent_slot_ge, ":agent_id", slot_agent_horse_prop,0),
      (agent_is_active, ":agent_id"),
      (agent_is_alive,":agent_id"),
      (agent_is_human,":agent_id"),
      (agent_is_non_player, ":agent_id"),

      (agent_get_team  ,":agent_team", ":agent_id"),
      (eq,":agent_team","$g_player_team"), #same team as player

      (agent_get_class,":class", ":agent_id"),
      (this_or_next|eq,":class","$g_class_listening"), #class or all
      (eq,"$g_class_listening",grc_everyone),

      (agent_get_horse, ":horse", ":agent_id"),
      (eq, ":horse", -1), #should not be mounted
      (agent_get_wielded_item, ":wielded_item", ":agent_id", 0),
      (gt, ":wielded_item", -1),
      # (is_between, ":wielded_item", ranged_weapons_begin, ranged_weapons_end),  #only ranged for now
      (item_get_type, ":item_type", ":wielded_item"),
      (this_or_next|is_between, ":wielded_item", grenades_begin, grenades_end),
	  (this_or_next|eq, ":item_type", itp_type_bow),
      #(this_or_next|eq, ":item_type", itp_type_crossbow),
      (this_or_next|eq, ":item_type", itp_type_pistol),
      (eq, ":item_type", itp_type_musket),

      # (agent_get_position,pos65,"$g_player"),
      # (agent_get_position,pos65,":agent_id"),
      (scene_prop_get_num_instances, ":total", "spr_cover"),
      (assign,":found",0),
      (assign,":found2",0),
      (assign,":enemy_nearby",0),

      (agent_ai_get_cached_enemy, ":enemy_agent", ":agent_id", 0),

      (try_for_range,":cur_instance",0,":total"),
        (neq,":found",1),
        (scene_prop_get_instance, ":instance_id", "spr_cover", ":cur_instance"),
        (scene_prop_slot_eq,":instance_id",scene_prop_cover_occupied, 0),

        (prop_instance_get_position, pos66, ":instance_id"),
        (get_distance_between_positions, ":dist", pos66, pos65),
        (le, ":dist", ":radius"), #prop lesser than 50m away
        # (neg|position_is_behind_position, pos65, pos66),

        (scene_prop_get_num_instances, ":total2", "spr_cover_enemy"),
        (try_for_range,":cur_instance2",0,":total2"),
          (neq,":found2",1),
          (scene_prop_get_instance, ":instance_id2", "spr_cover_enemy", ":cur_instance2"),

          (scene_prop_slot_eq,":instance_id2",scene_prop_cover_occupied, 1),

          (prop_instance_get_position, pos67, ":instance_id2"),
          (get_distance_between_positions, ":dist2", pos66, pos67),
          (le, ":dist2", 500),

          (assign,":found2",1),
        (try_end),

        (neq,":found2",1),

        #find nearest enemy agent
        # (agent_ai_get_cached_enemy, ":enemy_agent", ":agent_id", 0),
        (try_begin),
          (ge, ":enemy_agent", 0),

          (agent_is_active, ":enemy_agent"),
          (agent_is_alive, ":enemy_agent"),
          (agent_is_human,":enemy_agent"),

          (neg|agent_slot_ge, ":enemy_agent", slot_agent_is_running_away, 1),

          (agent_get_position, pos0, ":enemy_agent"),
          (get_distance_between_positions, ":new_distance", pos0, pos66), #distance enemy agent, choosen prop
          (lt, ":new_distance", ":dist"),
          (assign,":enemy_nearby",1),
        (try_end),

        (neq,":enemy_nearby",1),  #found enemy which is closer to the cover

        (assign,":found",1),

        (scene_prop_set_slot,":instance_id",scene_prop_cover_occupied,1),

        (try_begin),
          (eq,"$g_covers_active",1),     #this is with auto-cover positions, the block below for scenes with manual positioned covers.
          (agent_get_entry_no, ":entry", "$g_player"),
          # (agent_get_entry_no, ":entry", ":agent_id"),
          (entry_point_get_position, pos67, ":entry"),
          (try_begin),
            (neq,":agent_team","$g_player_team"),
            (position_rotate_z, pos67, 180),
          (try_end),

          (position_copy_origin,pos67,pos66),
          (try_begin),# krag add this block to move agents closer to thin cover props
			(scene_prop_slot_ge, ":instance_id", scene_prop_cover_distance_divider, 1),
			(position_move_y,pos67,-50,0),
		  (else_try),
			(position_move_y,pos67,-150,0), #cheap pos shift #just this line originally in this block - krag
		  (try_end),
          (agent_set_scripted_destination,":agent_id",pos67),
        (else_try),
          (agent_set_scripted_destination,":agent_id",pos66),
        (try_end),

        (agent_set_slot,":agent_id",slot_agent_take_cover,0),
        (agent_set_slot,":agent_id",slot_agent_prop_occupied,":instance_id"),
      (try_end),
    (try_end),
        ]),

#script_cover_search_player_single_agent
("cover_search_player_single_agent", #used for player autocover cycle - krag
  [
    #(store_script_param, ":order_pos", 1),
    (store_script_param, ":radius", 1),
    (store_script_param, ":agent_id", 2),
    (store_script_param, ":total", 3),
    (store_script_param, ":total2", 4),

    # (copy_position, pos65, ":order_pos"),

    # (try_for_agents, ":agent_id"),
      # (agent_slot_eq, ":agent_id", slot_agent_has_ranged,1),
      # (agent_slot_eq, ":agent_id", slot_agent_take_cover,-1),
      # (neg|agent_slot_ge, ":agent_id", slot_agent_horse_prop,0),
      # (agent_is_active, ":agent_id"),
      # (agent_is_alive,":agent_id"),
      # (agent_is_human,":agent_id"),
      # (agent_is_non_player, ":agent_id"),

       (agent_get_team  ,":agent_team", ":agent_id"),
      # (eq,":agent_team","$g_player_team"), #same team as player

      # (agent_get_class,":class", ":agent_id"),
      # (this_or_next|eq,":class","$g_class_listening"), #class or all
      # (eq,"$g_class_listening",grc_everyone),

      # (agent_get_horse, ":horse", ":agent_id"),
      # (eq, ":horse", -1), #should not be mounted
      # (agent_get_wielded_item, ":wielded_item", ":agent_id", 0),
      # (gt, ":wielded_item", -1),
      # # (is_between, ":wielded_item", ranged_weapons_begin, ranged_weapons_end),  #only ranged for now
      # (item_get_type, ":item_type", ":wielded_item"),
      # (this_or_next|eq, ":item_type", itp_type_bow),
      # (this_or_next|eq, ":item_type", itp_type_crossbow),
      # (this_or_next|eq, ":item_type", itp_type_pistol),
      # (eq, ":item_type", itp_type_musket),

      # (agent_get_position,pos65,"$g_player"),
       #(agent_get_position,pos65,":agent_id"), called in mt
      #(scene_prop_get_num_instances, ":total", "spr_cover"),
      (assign,":found",0),
      (assign,":found2",0),
      (assign,":enemy_nearby",0),

      (agent_ai_get_cached_enemy, ":enemy_agent", ":agent_id", 0),
	  
	  (position_move_y, pos65, 400, 0), #for attackers using position_is_behind_position to move forward below
	  
	  (agent_get_class, ":class", ":agent_id"),
	  (team_get_movement_order, ":cur_order", ":agent_team", ":class"),

	  (assign, reg13, 0),
      (try_for_range,":cur_instance",0,":total"),
        (neq,":found",1),
        (scene_prop_get_instance, ":instance_id", "spr_cover", ":cur_instance"),
        (scene_prop_slot_eq,":instance_id",scene_prop_cover_occupied, 0),

        (prop_instance_get_position, pos66, ":instance_id"),
        (get_distance_between_positions, ":dist", pos66, pos65),
        (le, ":dist", ":radius"), #prop lesser than 50m away
        # (neg|position_is_behind_position, pos65, pos66),
		
		(assign, ":continue", 1),
		(try_begin),
			(is_between, "$g_encountered_party", towns_begin, towns_end),
			(neq, ":agent_team", "$defender_team"),
			(neq, ":agent_team", "$defender_team_2"),
			(position_is_behind_position, pos66, pos65),	#attackers move forward
			(assign, ":continue", 0),
		  (else_try),
		    (eq,":agent_team","$g_player_team"),
			(neq, ":cur_order", mordr_hold),
			(neq, ":cur_order", mordr_stand_ground),
			(position_is_behind_position, pos66, pos65),	#everyone moves forward. 
			(assign, ":continue", 0),
		  (else_try),
		    (neg|is_between, "$g_encountered_party", towns_begin, towns_end),
			(neq,":agent_team","$g_player_team"),
			(position_is_behind_position, pos66, pos65),	#everyone moves forward. 
			(assign, ":continue", 0),
		(try_end),
		(eq, ":continue", 1),

        #(scene_prop_get_num_instances, ":total2", "spr_cover_enemy"),
        (try_for_range,":cur_instance2",0,":total2"),
          (neq,":found2",1),
          (scene_prop_get_instance, ":instance_id2", "spr_cover_enemy", ":cur_instance2"),

          (scene_prop_slot_eq,":instance_id2",scene_prop_cover_occupied, 1),

          (prop_instance_get_position, pos67, ":instance_id2"),
          (get_distance_between_positions, ":dist2", pos66, pos67),
          (le, ":dist2", 500),

          (assign,":found2",1),
        (try_end),

        (neq,":found2",1),

        #find nearest enemy agent
        # (agent_ai_get_cached_enemy, ":enemy_agent", ":agent_id", 0),
        (try_begin),
          (gt, ":enemy_agent", 0),

          (agent_is_active, ":enemy_agent"),
          (agent_is_alive, ":enemy_agent"),
          (agent_is_human,":enemy_agent"),

          (neg|agent_slot_ge, ":enemy_agent", slot_agent_is_running_away, 1),

          (agent_get_position, pos0, ":enemy_agent"),
          (get_distance_between_positions, ":new_distance", pos0, pos66), #distance enemy agent, choosen prop
          (val_mul, ":new_distance", 2), #double it as being in cover is still safer - krag
          (lt, ":new_distance", ":dist"),
          (assign,":enemy_nearby",1),
        (try_end),

        (neq,":enemy_nearby",1),  #found enemy which is closer to the cover

        (assign,":found",1),

        (scene_prop_set_slot,":instance_id",scene_prop_cover_occupied,1),

        (try_begin),
          (eq,"$g_covers_active",1),     #this is with auto-cover positions, the block below for scenes with manual positioned covers.
          (agent_get_entry_no, ":entry", "$g_player"),
          # (agent_get_entry_no, ":entry", ":agent_id"),
          (entry_point_get_position, pos67, ":entry"),
          (try_begin),
            (neq,":agent_team","$g_player_team"),
            (position_rotate_z, pos67, 180),
          (try_end),

          (position_copy_origin,pos67,pos66),
          (try_begin),# krag add this block to move agents closer to thin cover props
			(scene_prop_slot_ge, ":instance_id", scene_prop_cover_distance_divider, 1),
			(position_move_y,pos67,-50,0),
		  (else_try),
			(position_move_y,pos67,-150,0), #cheap pos shift #just this line originally in this block - krag
		  (try_end),
          (agent_set_scripted_destination,":agent_id",pos67),
        (else_try),
          (agent_set_scripted_destination,":agent_id",pos66),
        (try_end),

        (agent_set_slot,":agent_id",slot_agent_take_cover,0),
		(assign, reg11, 1),
		(assign, reg13, 1),
		(try_begin),
			(eq, "$g_autocover_messages", 1),
			(val_div, ":dist", 100),
			(assign, reg21, ":dist"),
			(str_store_agent_name, s21, ":agent_id"),
			(display_message, "@{s21} takes cover at {reg21}m."),
		(try_end),
		(agent_set_slot,":agent_id",slot_agent_prop_occupied,":instance_id"),
      (try_end),
    #(try_end),
        ]),
		

