#script_cover_ai_position
("cover_ai_position",
   [
    (try_for_agents, ":agent_id"),
      (agent_slot_eq, ":agent_id", slot_agent_take_cover, 0),
      # (agent_slot_eq, ":agent_id", slot_agent_has_ranged,1),
      (agent_is_active, ":agent_id"),
      (agent_is_human, ":agent_id"),
      (agent_is_non_player, ":agent_id"),

      # (agent_get_team, ":agent_team", ":agent_id"),
      (agent_get_position,pos65,":agent_id"),
      (agent_get_slot, ":instance_id", ":agent_id", slot_agent_prop_occupied),

      (prop_instance_get_position, pos16, ":instance_id"),
      (get_distance_between_positions, ":dist", pos16, pos65),
	  
	  # (agent_get_animation, ":anim", ":agent_id", 0),	#attempt to stop crouch sliding
	  # (try_begin),
			# (this_or_next|eq, ":anim", "anim_cover_crouch_to_stand"),
			# (eq, ":anim", "anim_cover_stand_to_crouch"),
			# (str_store_agent_name, s23, ":agent_id"),
			# (assign, reg22, ":anim"),
			# (display_message, "@{s23} crouch negated: {reg22}", message_negative),
			# #(agent_set_animation_progress, ":agent_id", 10000),
			# #(agent_set_animation, ":agent_id", "anim_stand", 0),
			# #(agent_set_animation, ":agent_id", "anim_jump", 0),
	  # (try_end),

      (try_begin),
        (eq,"$g_covers_active",1),     #this is with auto-cover positions, the block below for scenes with manual positioned covers.
		(try_begin),# krag add this block to move agents closer to thin cover props
			(scene_prop_slot_ge, ":instance_id", scene_prop_cover_distance_divider, 1),
			(lt, ":dist", 50),
			(agent_set_slot,":agent_id",slot_agent_take_cover,1),
			(agent_set_speed_modifier, ":agent_id", 0), #freeze them
			
			(agent_get_position, pos18, ":agent_id"),
			(agent_set_scripted_destination, ":agent_id", pos18, 1, 1),	#attempt to stop them trying to shuffle around constantly around
			
			(store_mission_timer_a, ":time"),
			  (val_add, ":time", 15),
			  (agent_set_slot, ":agent_id", slot_agent_last_time_hit_enemy, ":time"),	#for leaving cover if not shot in a while
		  (else_try),
			(lt, ":dist", 350), #just these 3 lines originally
			(agent_set_slot,":agent_id",slot_agent_take_cover,1),
			(agent_set_speed_modifier, ":agent_id", 0), #freeze them
			
			(agent_get_position, pos18, ":agent_id"),
			(agent_set_scripted_destination, ":agent_id", pos18, 1, 1),
			
			(store_mission_timer_a, ":time"),
			  (val_add, ":time", 15),
			  (agent_set_slot, ":agent_id", slot_agent_last_time_hit_enemy, ":time"),
		(try_end),
      (else_try),
        (lt, ":dist", 100),
        (agent_set_slot,":agent_id",slot_agent_take_cover,1),
        (agent_set_speed_modifier, ":agent_id", 0), #freeze them
		
		(agent_get_position, pos18, ":agent_id"),
		(agent_set_scripted_destination, ":agent_id", pos18, 1, 1),
		
		(store_mission_timer_a, ":time"),
		  (val_add, ":time", 15),
		  (agent_set_slot, ":agent_id", slot_agent_last_time_hit_enemy, ":time"),
      (try_end),
    (try_end),
	
	

    ]),

