# script_cf_weather_change
("cf_weather_change",
    [
        (get_global_cloud_amount, "$g_cloud"),
        (get_global_haze_amount, "$g_fog"),

        (party_get_current_terrain, ":terrain_type", "p_main_party"),

        (call_script, "script_rnd", 0,3),
        (eq,reg0,1), #do change

        (assign,"$g_thunder",0),

        (call_script, "script_rnd", 0,10),
        (try_begin), #sunny
          (is_between,reg0,0,4),
          (assign,"$g_rain",0),
          (call_script, "script_rnd", 0,25),
          (assign,"$g_cloud",reg0),
          (set_global_cloud_amount,"$g_cloud"),

          #fog
          (try_begin),
            (call_script, "script_rnd", 0,2),
            (eq,reg0,1),
            (assign,"$g_fog",0),
            (set_global_haze_amount,"$g_fog"),
          (try_end),

          #sandstorm
          (try_begin),
            (this_or_next|eq,":terrain_type",rt_snow_forest),
            (eq,":terrain_type",rt_snow),

            (call_script, "script_rnd", 0,150),
            (eq,reg0,1),
            (assign,"$g_sandstorm",1),
          (else_try),
            (this_or_next|eq,":terrain_type",rt_desert),
            (eq,":terrain_type",rt_desert_forest),

            (call_script, "script_rnd", 0,100),
            (eq,reg0,1),
            (assign,"$g_sandstorm",1),
          (else_try),
            (assign,"$g_sandstorm",0),
          (try_end),
        (else_try), #bit cloudy
          (is_between,reg0,4,6),
          (assign,"$g_rain",0),
          (call_script, "script_rnd", 25,50),
          (assign,"$g_cloud",reg0),
          (set_global_cloud_amount,"$g_cloud"),
          #fog
          (try_begin),
            (call_script, "script_rnd", 0,2),
            (eq,reg0,1),
            (assign,"$g_fog",0),
            (set_global_haze_amount,"$g_fog"),
          (try_end),
        (else_try), #cloudy
          (is_between,reg0,6,8),
          #rain
          (try_begin),
            (this_or_next|eq,":terrain_type",rt_snow_forest),
            (eq,":terrain_type",rt_snow),

            (call_script, "script_rnd", 0,20),
            (eq,reg0,1),
            (assign,"$g_rain",1),
          (else_try),
            (this_or_next|eq,":terrain_type",rt_desert),
            (eq,":terrain_type",rt_desert_forest),

            (call_script, "script_rnd", 0,25),
            (eq,reg0,1),
            (assign,"$g_rain",1),
          (else_try),
            (neq,":terrain_type",rt_desert),
            (neq,":terrain_type",rt_desert_forest),
            (neq,":terrain_type",rt_snow_forest),
            (neq,":terrain_type",rt_snow),

            (call_script, "script_rnd", 0,15),
            (eq,reg0,1),
            (assign,"$g_rain",1),
          (else_try),
            (assign,"$g_rain",0),
          (try_end),

          (call_script, "script_rnd", 50,75),
          (assign,"$g_cloud",reg0),
          (set_global_cloud_amount,"$g_cloud"),
        (else_try), #very cloudy
          (is_between,reg0,8,10),
          #rain
          (try_begin),
            (this_or_next|eq,":terrain_type",rt_snow_forest),
            (eq,":terrain_type",rt_snow),

            (call_script, "script_rnd", 0,15),
            (eq,reg0,1),
            (assign,"$g_rain",1),
            (call_script, "script_rnd", 0,3),
            (eq,reg0,1),
            (assign,"$g_thunder",1),
          (else_try),
            (this_or_next|eq,":terrain_type",rt_desert),
            (eq,":terrain_type",rt_desert_forest),

            (call_script, "script_rnd", 0,20),
            (eq,reg0,1),
            (assign,"$g_rain",1),
            (call_script, "script_rnd", 0,3),
            (eq,reg0,1),
            (assign,"$g_thunder",1),
          (else_try),
            (neq,":terrain_type",rt_desert),
            (neq,":terrain_type",rt_desert_forest),
            (neq,":terrain_type",rt_snow_forest),
            (neq,":terrain_type",rt_snow),

            (call_script, "script_rnd", 0,10),
            (eq,reg0,1),
            (assign,"$g_rain",1),
            (call_script, "script_rnd", 0,3),
            (eq,reg0,1),
            (assign,"$g_thunder",1),
          (else_try),
            (assign,"$g_rain",0),
            (call_script, "script_rnd", 0,100),
            (eq,reg0,1),
            (assign,"$g_thunder",1),
          (try_end),

          (call_script, "script_rnd", 75,101),
          (assign,"$g_cloud",reg0),
          (set_global_cloud_amount,"$g_cloud"),
        (try_end),]),

