#script_center_scavenged
("center_scavenged",
	[
            (display_message, "@Supplies scavenged!", message_positive),
            # (store_random_in_range,":rand",1,5),
            (try_begin),
                (party_slot_eq, "$current_town", slot_center_scavenge, 1),

                (prop_instance_get_position, pos1, "$resource_prop_id"),
                (set_spawn_position, pos1),
                (spawn_scene_prop, "spr_prop_resource_boxes_empty"),
                (position_move_z, pos1, -500),
                (position_rotate_x, pos1, 90),
                (prop_instance_animate_to_position, "$resource_prop_id", pos1, 50),

                (try_for_range,":unused",0,3),
                    (store_random_in_range,":food",food_begin,drink_end),
                    (store_random_in_range,":rand",1,4),
                    (troop_add_items, "trp_player", ":food", ":rand"),
                (try_end),
            (else_try),
                (party_slot_eq, "$current_town", slot_center_scavenge, 2),

                (prop_instance_get_position, pos1, "$resource_prop_id"),
                (set_spawn_position, pos1),
                (spawn_scene_prop, "spr_prop_resource_ammo_empty"),
                (position_move_z, pos1, -500),
                (position_rotate_x, pos1, 90),
                (prop_instance_animate_to_position, "$resource_prop_id", pos1, 50),

                (try_for_range,":unused",0,3),
                    (store_random_in_range,":food",firearm_ammo_begin,firearm_ammo_end),
                    # (store_random_in_range,":rand",1,4),
                    (troop_add_items, "trp_player", ":food", 1),
                (try_end),
            (else_try),
                (party_slot_eq, "$current_town", slot_center_scavenge, 3),

                (prop_instance_get_position, pos1, "$resource_prop_id"),
                (set_spawn_position, pos1),
                (spawn_scene_prop, "spr_prop_resource_ammo_box_empty"),
                (position_move_z, pos1, -500),
                (position_rotate_x, pos1, 90),
                (prop_instance_animate_to_position, "$resource_prop_id", pos1, 50),

                (try_for_range,":unused",0,5),
                    (store_random_in_range,":food",trade_goods_begin,trade_goods_end),
                    (troop_add_items, "trp_player", ":food", 1),
                (try_end),
            (try_end),
            (play_sound, "snd_dummy_destroyed"),
            (party_set_slot,"$current_town", slot_center_scavenge, -1),

            (try_for_agents, ":agent"),
                (agent_is_human, ":agent"),
                (agent_is_alive, ":agent"),
                (agent_slot_eq, ":agent", slot_agent_walker_occupation, 2),
                (agent_set_slot, ":agent", slot_agent_walker_occupation, 1),
            (try_end),
	]),

