# script_get_page_no_of_troop_tree_for_troop_on
# Input: troop_no
# Output: page_no
("get_page_no_of_troop_tree_for_troop_on",
  [
      (store_script_param, ":troop_no", 1),

      (store_sub, ":num_factions", npc_kingdoms_end, npc_kingdoms_begin),
      (store_troop_faction, ":troop_faction", ":troop_no"),
      (try_begin),
        (is_between, ":troop_faction", npc_kingdoms_begin, npc_kingdoms_end),
        (store_sub, ":page_no", ":troop_faction", npc_kingdoms_begin),
      (else_try),
        (is_between, ":troop_no", soldiers_begin, mercenary_troops_end),
        (store_add, ":page_no", ":num_factions", 0), # mercenary
      (else_try),
        (eq, ":troop_faction", "fac_outlaws"),
        (store_add, ":page_no", ":num_factions", 1), # Outlaws
      (else_try),
        (store_add, ":page_no", ":num_factions", 2), # Others
      (try_end),
      (assign, reg0, ":page_no"),
  ]),

("sort_created_party", [
     #sort template troops
     (try_for_parties, ":party_no"),
        (assign, ":continue", 0),
        (try_begin),
            (party_slot_eq, ":party_no", slot_party_type, spt_bandit_party),
            (party_is_active, ":party_no"),
            (assign, ":continue", 1),
            (try_begin),
                (party_stack_get_troop_id, ":cur_troop", ":party_no", 0),
                (troop_is_hero, ":cur_troop"),
                # (eq, ":cur_troop", "trp_caravan_master"),
                (assign, ":first_stack", 1),
            (else_try),
                (assign, ":first_stack", 0),
            (try_end),
        (try_end),
        (eq, ":continue", 1),
        (party_get_num_companion_stacks, ":num_stacks", ":party_no"),
        (gt, ":num_stacks", ":first_stack"),
        (assign, ":last_stack", ":num_stacks"),

        # start to sort
        (store_sub, ":num_times", ":num_stacks", ":first_stack"),
        (try_for_range, ":unused", 0, ":num_times"),
            # find highest-level troop
            (assign, ":best_stack", -1),
            (assign, ":best_level", -1),
            (try_for_range, ":cur_stack", ":first_stack", ":last_stack"),
                (party_stack_get_troop_id, ":cur_troop", ":party_no", ":cur_stack"),
                (store_character_level, ":troop_level", ":cur_troop"),
                (gt, ":troop_level", ":best_level"),
                (assign, ":best_level", ":troop_level"),
                (assign, ":best_stack", ":cur_stack"),
            (try_end),
            # move to the end
            (try_begin),
                (gt, ":best_level", -1),
                (party_stack_get_troop_id, ":stack_troop", ":party_no", ":best_stack"),
                (party_stack_get_size, ":stack_size", ":party_no", ":best_stack"),
                (party_stack_get_num_wounded, ":num_wounded", ":party_no", ":best_stack"),
                (party_remove_members, ":party_no", ":stack_troop", ":stack_size"),
                (party_add_members, ":party_no", ":stack_troop", ":stack_size"),
                (party_wound_members, ":party_no", ":stack_troop", ":num_wounded"),
                (val_sub, ":last_stack", 1),
            (try_end),
        (try_end),
     (try_end),

    ]),

# script_debug_pos
