#("script_lookat", pos##, pos##),
		#This script will take a position and rotate it such that +Y will face the target exactly.
		#It does this with some basic trig, I'll explain it in the comments inside the script.
		#INPUT:
		#	Param 1: Positional register of the pos## that will be rotated
		#	Param 2: Positional register of the pos## that will be targeted
		#OUTPUT:
		#	N/A
("lookat",
	[
	(set_fixed_point_multiplier, 100),
	(store_script_param, ":looker", 1),		# This is the positional register that will turn to face the :target (+Y being forward)
	(store_script_param, ":target", 2),		# This is the positional register that will be targeted

	(init_position, pos13),
	(assign, ":local", pos13),				# This just makes the local_var :local equivalent to pos13

	(init_position, pos1),						# Get a clean positional register so. . .
	(position_copy_rotation, ":looker", pos1),	# We can scrub the rotational data from the :looker to simplify the math

	# The maths are pretty easy once we figure it out. Essentially, make two triangles with the two positions
	# Use those triangles to determine the angles that the :looker will need to rotate to face the :target

	(position_transform_position_to_local, ":local", ":looker", ":target"),	# We will use the local data to determine side lengths

	(position_get_z, ":l_z", ":looker"),		# :looker z value

	(position_get_z, ":t_z", ":target"),		# :target z value

	(position_get_x, ":local_x", ":local"),		# The opposite side of the first triangle
	(position_get_y, ":local_y", ":local"),		# The adjacent side of the first triangle

	(store_sub, ":z_dis", ":l_z", ":t_z"),		# The adjacent side of the second triangle

	(get_distance_between_positions, ":hypo", ":looker", ":target"),	# Distance between the positions will be the hypotenuse of both triangles

	(convert_to_fixed_point, ":z_dis"),		# When doing fixed point maths only one needs to be fixed point or else it won't convert from the fp correctly
	(convert_to_fixed_point, ":local_x"),	# When doing fixed point maths only one needs to be fixed point or else it won't convert from the fp correctly

		# SOH CAH TOA, sin(opp/hyp), cos(adj/hyp), tan(opp/adj)

	(store_div, ":adj_hyp", ":z_dis", ":hypo"),	# Use the second triangle's adjacent / hypotenuse

	(store_acos, ":x_angle", ":adj_hyp"),		# To get the angle we need to adjust the pitch
	(convert_from_fixed_point, ":x_angle"),		# Convert from fixed point to make it usable by the rotation
	(val_add, ":x_angle", 270),					# Move it by 270 degrees to convert the angle into the correct quadrant

	(try_begin),
		(eq, ":local_y", 0),					# If the adjacent side's length would be 0
		(assign, ":z_angle", 0),				# Set the yaw to 0 to prevent division by zero errors
	(else_try),
		(store_div, ":opp_adj", ":local_x", ":local_y"),	# Use the second triangle's opposite side / adjacent side
		(store_atan, ":z_angle", ":opp_adj"),				# To get the angle of the yaw
		(convert_from_fixed_point, ":z_angle"),				# Convert from fixed point to make it usable by the rotation
		(val_mul, ":z_angle", -1),							# Mirror the yaw to change it from CCW to CW
	(try_end),

	(try_begin),
		(lt, ":local_y", 0),			# If the :target is behind the :looker
		(val_add, ":z_angle", 180),		# Move the yaw 180 degrees
	(try_end),


	(position_rotate_z, ":looker", ":z_angle"),	# Rotate left/right (yaw) first
	(position_rotate_x, ":looker", ":x_angle"),	# Then rotate up/down (pitch) last
	]),

("sort_agents_by_distance", #dstn
        [
        # Input Variables
        (store_script_param, ":player_agent", 1),
        (store_script_param, ":player_pos", 2),

        # Variables
        (assign, ":array_slot", 0),                        # To sort, first store unsorted from 1 to total agents
        #(assign, ":minimum_slot", 0),                    # Iterate through all agent distances and store the lowest in slot 0
        (assign, ":agent_array", "trp_temp_array_a"),    # Then move to slot 2, iterate through unsorted and store lowest in 1
        (assign, ":adist_array", "trp_temp_array_b"),    # etc, etc, etc. Loop until you've gone through all the agents in a scene.

        (try_for_range, ":i", 0, 1000),
            (troop_set_slot, ":agent_array", ":i", 0), #agent id
        (try_end),

        (try_for_range, ":i", 0, 1000),
            (troop_set_slot, ":adist_array", ":i", 0), # distance from player
        (try_end),


        (try_for_agents, ":agent"),                                                    # Iterate through all agents
            (neq, ":agent", ":player_agent"),                                        # That are not the player
            (agent_is_human, ":agent"),                                                # And that are human

            (agent_get_position, pos45, ":agent"),                                    # Where are they?
            (get_distance_between_positions, ":distance", ":player_pos", pos45),    # How far is that from the player?

            (troop_set_slot, ":agent_array", ":array_slot", ":agent"),                # Store this agent in a slot numbered ge, 1
            (troop_set_slot, ":adist_array", ":array_slot", ":distance"),            # Store this distnace in a slot numbered ge, 1

            (val_add, ":array_slot", 1),                                            # Iterate that slot after this.
        (try_end),

        (assign, reg45, ":array_slot"),

        (try_for_range, ":i", 0, ":array_slot"),                                    # Use the count from above to iterate through the array slots

            (assign, ":comp_dist", 999999),                                            # Large number to check against

            (try_for_range, ":j", ":i", ":array_slot"),                                # Loops in Loops
                (troop_get_slot, ":adist", ":adist_array", ":j"),                    # Check the distance stored in slot j
                (lt, ":adist", ":comp_dist"),                                        # If less than the previous comparison number
                (neq, ":adist", 0),
                (assign, ":comp_dist", ":adist"),                                    # Replace it, and,
                (assign, ":nearest", ":j"),                                            # Remember what slot I used to be in
            (try_end),

            (troop_get_slot, ":nearest_agent", ":agent_array", ":nearest"),            # Take the remembered slot and pull the assoc. agent
            (troop_get_slot, ":nearest_distance", ":adist_array", ":nearest"),        # Take the remembered slot and pull the assoc. distance

            (troop_get_slot, ":swap_agent", ":agent_array", ":i"),        # Take the previously stored agent
            (troop_get_slot, ":swap_distance", ":adist_array", ":i"),    # Take the previously stored distance

            (troop_set_slot, ":agent_array", ":nearest", ":swap_agent"),            # Store this swapped agent to whereever the nearest used to live
            (troop_set_slot, ":adist_array", ":nearest", ":swap_distance"),         # Store this swapped distance to whereever the nearest used to live


            (troop_set_slot, ":agent_array", ":i", ":nearest_agent"),    # Store this nearest agent in a slot numbered ge, 0
            (troop_set_slot, ":adist_array", ":i", ":nearest_distance"), # Store this nearest distance in a slot numbered ge, 0
        (try_end),

        ]
    ),


#script_random_scene_pos
#Output: pos6
("random_scene_pos",
  [
		(get_scene_boundaries, pos11, pos12),
     (position_get_x, "$g_scene_min_x", pos11),
     (position_get_y, "$g_scene_min_y", pos11),
	 (position_get_x, "$g_scene_max_x", pos12),
     (position_get_y, "$g_scene_max_y", pos12),
    (store_div,":border_x","$g_scene_max_x", 2400),
    (store_add, ":scene_min_x", "$g_scene_min_x",":border_x"),
    (store_sub, ":scene_max_x", "$g_scene_max_x",":border_x"),
    (store_div,":border_y","$g_scene_max_y", 2400),
    (store_add, ":scene_min_y","$g_scene_min_y",":border_y"),
    (store_sub, ":scene_max_y","$g_scene_max_y",":border_y"),
	(call_script, "script_rnd", ":scene_min_x",":scene_max_x"),
	(assign, ":x_pos", reg0),
	(call_script, "script_rnd", ":scene_min_y",":scene_max_y"),
	(assign, ":y_pos", reg0),
	(init_position, pos6),
	(position_set_x, pos6, ":x_pos"),
	(position_set_y, pos6, ":y_pos"),
	(position_rotate_z, pos6, ":x_pos", 1),
    (position_set_z,pos6,10000), #"random" rotation
    (position_set_z_to_ground_level,pos6),
		(try_begin),
			(get_player_agent_no, ":player"),
			(gt, ":player", -1),
			(agent_get_position, pos2, ":player"),
			(get_distance_between_positions, ":dist", pos2, pos6),
			(lt, ":dist", 17000), #170m
			(call_script, "script_random_scene_pos"),
		(try_end),

	]
	 ),

# script_rnd
# Input: arg1 = min arg2 = max
# Output: reg0 = random_number
# Will only work up to about a billion
("rnd",[
    (store_script_param_1, ":min"),
    (store_script_param_2, ":max"),

    (val_mul,"$rand_seed",1664525), # see: Numerical Recipes in C
    (val_add,"$rand_seed",1013904223), # Any two odd, relatively prime numbers larger than 65536 will do

    (val_sub,":max",":min"),
    (try_begin),
      (gt,":max",1),
      # Handle negative numbers; store_mod is not safe there!
      (store_mod,":r","$rand_seed",1024*1024*1024),
      (try_begin),
        (lt, ":r", 0),
        (val_add,":r",1024*1024*1024),
      (try_end),
      (store_div,":range",1024*1024*1024,":max"),
      (val_div,":r",":range"),
      (try_begin),
        # Make sure we didn't exceed our range.
        # Should happen very rarely, so we can afford to be lazy and use recursion.
        (eq,":r",":max"),
        (call_script,"script_rnd",0,":max"),
        (val_add,reg0,":min"),
      (else_try),
        (store_add,reg0,":min",":r"),
      (try_end),
    (else_try),
      (assign,reg0,":min"),
    (try_end),
    ]),

