          (scene_prop_set_visibility, ":wheel_left", 0),
          (scene_prop_set_visibility, ":wheel_right", 0),
          (scene_prop_set_visibility, ":wheel_left2", 0),
          (scene_prop_set_visibility, ":wheel_right2", 0),

