("camp_quality",
	[
    #inventory
    (assign, ":total_item_value", 0),
    (assign, ":total_effect", 0),
    (try_for_range, ":item", trade_goods_begin, trade_goods_end),
      (item_set_slot, ":item", slot_item_is_checked, 0),
    (try_end),
    (troop_get_inventory_capacity, ":capacity", "trp_player"),
    (try_for_range, ":i_inv", 0, ":capacity"),
      (troop_get_inventory_slot, ":item", "trp_player", ":i_inv"),
      (ge, ":item", 0),
      (is_between,":item",trade_goods_begin,trade_goods_end),
      (item_slot_eq, ":item", slot_item_is_checked, 0),
      (item_set_slot, ":item", slot_item_is_checked, 1),

      (item_get_food_quality, ":item_value", ":item"),
      (gt, ":item_value", 0),
      # (store_item_value, ":item_value", ":item"),
      (val_add, ":total_item_value", ":item_value"),
    (try_end),
    # (store_div, ":total_item_value_effect", ":total_item_value", 200),
    (store_div, ":total_effect", ":total_item_value",10),	#was 10 but less generic trade good trash now. - krag
    (val_clamp, ":total_effect",0,101),
    # (val_div, ":total_effect",4),
    (assign, "$g_camp_quality", ":total_effect"), #zero to 100

	]),

