        (set_fixed_point_multiplier, 100),
        (party_get_position, pos1, "p_main_party"),
        (position_get_x, ":middle_x", pos1),
        (position_get_y, ":middle_y", pos1),
        (assign, ":break", 622),#2 pi times 100
        (assign, ":radius", 1),
        (convert_to_fixed_point, ":radius"),
        (val_div, ":radius", 100),
        (try_for_range, ":angle", 0, ":break"),
