# script_warzone_ambience_sound
("warzone_ambience_sound",
  [
    (store_script_param, ":terrain_type", 1),

    (stop_sound_channel, "$ambient_sound_channel"),

    (try_begin),
      (eq, "$g_sandstorm",1),

      (play_sound, "snd_ambient_sandstorm", sf_looping),
	  #(play_track, "track_ambient_sandstorm", 1),
    (else_try),
      (ge, "$g_cloud",75),
      (this_or_next|eq,"$g_thunder",1),
      (ge, "$g_fog",25),

      (play_sound, "snd_ambient_storm", sf_looping),
    (else_try),
      (neq, "$talk_context", 0),
	  (is_between,"$g_encountered_party",towns_begin,towns_end),
      (party_slot_eq, "$g_encountered_party", slot_party_type, spt_town),
      (neg|is_currently_night),

      (play_sound, "snd_ambient_town", sf_looping),
    (else_try),
      (neg|is_currently_night),
      (try_begin),
        (ge, "$g_cloud",50),
        (play_sound, "snd_ambient_wind_day", sf_looping),
      (else_try),
        (neq,":terrain_type",rt_plain),
        (neq,":terrain_type",rt_forest),
        (neq,":terrain_type",rt_snow_forest),

        (play_sound, "snd_ambient_day", sf_looping),
      (else_try),
        (play_sound, "snd_ambient_plain_day", sf_looping),
      (try_end),
    (else_try),
      (try_begin),
        (ge, "$g_cloud",50),
        (play_sound, "snd_ambient_wind_night", sf_looping),
      (else_try),
        (neq,":terrain_type",rt_plain),
        (neq,":terrain_type",rt_forest),
        (neq,":terrain_type",rt_snow_forest),

        (play_sound, "snd_ambient_night", sf_looping),
      (else_try),
        (play_sound, "snd_ambient_plain_night", sf_looping),
      (try_end),
    (try_end),
    (store_last_sound_channel, "$ambient_sound_channel"),
  ]),

