("helicopter_crash", [
(store_script_param, ":instance_no", 1),
(store_script_param, ":attacker_agent_no", 2),

		
		(scene_prop_get_slot, ":horse", ":instance_no", scene_prop_attached_horse),
		(try_for_agents, ":agents"),
			(agent_is_active, ":attacker_agent_no"),
			(agent_slot_eq, ":agents", slot_agent_rides_x,":horse"),
			(agent_is_alive, ":agents"),
			(agent_deliver_damage_to_agent, ":attacker_agent_no", ":agents", 500),
		(try_end),
		
		(scene_prop_get_slot, ":attached_left", ":instance_no", scene_prop_attached_left),
		(scene_prop_get_slot, ":attached_right", ":instance_no", scene_prop_attached_right),
		#(agent_deliver_damage_to_agent, ":attacker_agent_no", ":horse", 1000),
		(agent_fade_out, ":horse", 0),
		(prop_instance_stop_all_particle_systems, ":attached_left"),
		(scene_prop_fade_out, ":attached_left", 1),
		(scene_prop_fade_out, ":attached_right", 1),
		(prop_instance_stop_sound, ":instance_no"),

		#(prop_instance_deform_in_range, ":instance_no", 1, 22, 1000),
		(play_sound, "snd_grenade1"),

		(prop_instance_get_position, pos12, ":instance_no"),
		(particle_system_burst, "psys_larger_explosion", pos12, 100),
		
		(position_move_y, pos12, 1500),
		(position_set_z_to_ground_level, pos12),
		#(particle_system_burst, "psys_village_fire_big", pos12, 100),
		(particle_system_burst, "psys_village_fire_big", pos12, 1000),
		(particle_system_burst, "psys_village_fire_smoke_big", pos12, 1000),
		
		(position_move_z, pos12, -730),
		#(store_random_in_range
		#(position_rotate_z, pos12, 45),
		#(position_rotate_y, pos12, 45),
		#(position_rotate_z, pos12, 45),
		(prop_instance_animate_to_position, ":instance_no", pos12, 130),
		#(particle_system_burst, "psys_village_fire_big", pos12, 100),
		#(particle_system_burst, "psys_village_fire_smoke_big", pos12, 100),
]),

